<?php require 'config.php';$term=trim($_GET['q']??'');$sql="SELECT * FROM jobs WHERE deadline IS NULL OR deadline>=CURDATE()";$args=[];if($term!==''){$sql.=" AND (title LIKE ? OR company LIKE ? OR location LIKE ?)";$like="%$term%";$args=[$like,$like,$like];}$sql.=" ORDER BY created_at DESC";$q=$pdo->prepare($sql);$q->execute($args);$jobs=$q->fetchAll();include 'header.php';?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><h2>Available Opportunities</h2><form class="d-flex" method="get"><input class="form-control me-2" name="q" value="<?=h($term)?>" placeholder="Search title/company/location"><button class="btn btn-primary">Search</button></form></div>
<div class="row g-3"><?php foreach($jobs as $j):?><div class="col-md-6"><div class="card p-4 h-100"><div class="d-flex justify-content-between"><h5><?=h($j['title'])?></h5><span class="badge text-bg-primary">Open</span></div><p class="text-primary fw-semibold mb-1"><?=h($j['company'])?></p><p class="text-secondary"><?=h($j['location'])?> · Deadline: <?=h($j['deadline']?:'Not specified')?></p><p><?=nl2br(h($j['description']))?></p><?php if($j['eligibility']):?><p><b>Eligibility:</b> <?=h($j['eligibility'])?></p><?php endif;?><?php if(!empty($_SESSION['user_id'])&&($_SESSION['role']??'')==='student'):?><form method="post" action="apply.php"><input type="hidden" name="job_id" value="<?=$j['id']?>"><button class="btn btn-primary">Apply Now</button></form><?php elseif(empty($_SESSION['user_id'])):?><a class="btn btn-outline-primary" href="login.php">Login to Apply</a><?php endif;?></div></div><?php endforeach;?></div><?php if(!$jobs):?><div class="alert alert-info">No matching opportunities found.</div><?php endif;?><?php include 'footer.php';?>